// Old docs versions (generated by `starlight-versions`) that are kept online
// for existing users but kept out of search results: their canonical URL points
// to the current docs (see `src/routeData.ts`) and they are excluded from the
// sitemap (see `astro.config.mjs`).
export const ARCHIVED_DOCS_VERSIONS = ["0.23"];

/** Strips a leading archived version segment, e.g. `/0.23/guides/` -> `/guides/`. */
export function getCurrentDocsPathname(pathname) {
  const version = ARCHIVED_DOCS_VERSIONS.find((v) =>
    pathname.startsWith(`/${v}/`),
  );
  return version ? pathname.slice(version.length + 1) : undefined;
}
